const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms));
const assert=(v,m)=>{if(!v)throw Error(m);},button=a=>`[data-deck="1"][data-action="${a}"]`;
const click=s=>{assert($(s),'Missing '+s);$(s).click();};
const files=['app.js','engine.js','panels.js','styles.css','fixtures/sampler-fallback-178-short-loop.json','manual-loops.js','beatgrid.js','smart-sync.js','sync-tempo-handoff.js','sampler-sync.js','sample-sync-transport.js','warp-loop.js','warp-loop-kernel.js','warp-loop-worklet.js','stems.js','keylock.js','keylock-worker.js','keylock-dsp.js','track-gain.js','sampler-ownership-180-harness.js','stem-activation-capture-145.js','vendor/signalsmith-stretch/SignalsmithStretch-open-play-reference-dsp.mjs'];
const sha=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');
async function identities(){return Object.fromEntries(await Promise.all(files.map(async f=>{const response=await fetch(f,{cache:'no-store'});assert(response.ok,f);return[f,await sha(await response.arrayBuffer())];})));}
async function until(fn,label,ms=30000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
function input(selector,value){const el=$(selector);assert(el,selector);if(typeof value==='boolean')el.checked=value;else el.value=String(value);el.dispatchEvent(new Event('input',{bubbles:true}));}
function base64(bytes){let value='';for(let i=0;i<bytes.length;i+=16384)value+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(value);}
let app,readiness;
async function run(){
 clearInterval(readiness);$('#music-run').disabled=true;const {state,engine}=app,d=state.decks[0],taps=[],witnesses=[],connections=[],ids=new WeakMap();let nextID=0,track,file,zero,stereo;
 const r={checkpoint:150,diagnosticCheckpoint:180,samples:[],stages:[],errors:[],uiErrors:[],sourceBefore:await identities(),startedAt:new Date().toISOString(),scope:'Actual keyed preparation and actual synchronize resolution observers forward original promises/results unchanged, queue normal deck Stop/load or sample Stop; other sample audio/owner retained. Native streams/feedback, not vendor race semantics/native/hardware/full parity.'};
 const id=v=>{if(v&&!ids.has(v))ids.set(v,++nextID);return v?ids.get(v):null;};
 const snap=()=>({at:engine.ctx.currentTime,deck:{track:d.track.id,playing:d.playing,processing:d.processing,queued:!!d.playQueued,sync:d.sync,state:d.syncState,role:d.syncRole,keylock:d.keylock,position:engine.position(d),voiceID:id(engine.voices.get(0)),token:engine.startTokens.get(0),hasTransform:engine.transforms.has(0)},samples:[0,1].map(k=>({key:k,voiceID:id(engine.samples?.get(k)),request:engine.sampleRequests.has(k),slot:{...state.samples[0][k]}}))});
 const unhandled=e=>{r.uiErrors.push({message:e.reason?.message||String(e.reason),stack:e.reason?.stack});e.preventDefault();};window.addEventListener('unhandledrejection',unhandled);
 async function configure(k,sync){click(`[data-track="${track.id}"]`);const off=$(`[data-sample-sync="${k}"][data-sync-action="off"]`);if(!off.disabled)off.click();click(`[data-sample="${k}:load"]`);await until(()=>state.samples[0][k].track===track.id,'Load sample');click(`[data-sample="${k}:advanced"]`);await until(()=>$('#sample-from'),'Advanced');input('#sample-from','loop:1');input('#sample-gain',0);input('#sample-volume',80);input('#sample-pitch',0);input('#sample-keylock',false);click('#sample-apply');if(!$(`[data-sample-repeat="${k}"]`).checked)$(`[data-sample-repeat="${k}"]`).click();if(sync)click(`[data-sample-sync="${k}"][data-sync-action="on"]`);click(`[data-sample="${k}:play"]`);await until(()=>engine.samples?.get(k)&&!state.samples[0][k].processing&&engine.ctx.currentTime>engine.samples.get(k).anchorTime+.05,'Sample playing');}
 async function reset(){if(d.playing||d.processing||d.playQueued){click('[data-deck="0"][data-action="play"]');await until(()=>!d.playing&&!d.processing&&!d.playQueued,'Pause prior deck');}if(d.sync)click('[data-deck="0"][data-action="syncOff"]');await until(()=>!d.sync,'Deck Off');click(`[data-track="${track.id}"]`);click('[data-deck="0"][data-action="load"]');await until(()=>d.track===track&&!d.processing,'Research deck load');if(!d.keylock)click('[data-deck="0"][data-action="keylock"]');await until(()=>d.keylock&&!d.processing,'Key Lock enabled');if(engine.samples?.has(0))click('[data-sample="0:stop"]');await configure(0,true);click('[data-deck="0"][data-action="sync"]');await until(()=>d.sync&&!d.processing,'Arm sample-led deck');}
 function attach(){for(const [source,dest]of connections.splice(0))try{source.disconnect(dest);}catch{};for(const tap of taps){const source=tap.label==='deck'?engine.nodes[0].deckInput:tap.label==='bus'?engine.samplerOutput:engine.samples?.get(Number(tap.label.slice(-1)))?.gain;if(source){source.connect(tap.input);connections.push([source,tap.input]);}}}
 async function capture(seconds){return Promise.all(witnesses.map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM timeout')),10000);w.port.onmessage=async({data})=>{if(data.type==='done'){clearTimeout(timer);resolve({label:w.label,channel:w.channel,startFrame:data.startFrame,frames:data.data.length,quanta:data.quanta,errors:data.errors,sha256:await sha(data.data.buffer),base64:base64(new Uint8Array(data.data.buffer))});}};w.port.postMessage({type:'capture',id:'ownership180',frames:Math.round(seconds*engine.ctx.sampleRate)});})))}
 try{
  r.context={sampleRate:engine.ctx.sampleRate,requestedSampleRate:null};await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical mute');track=state.tracks.find(t=>t.contentHash==='cb2e756d1fa4ce264767a4f6adbaf9e3f69a040db7889d830abdb429cc1a5ac3');assert(track&&track.bpm===120&&track.grid===0,'Declared fixture');await until(()=>!state.analysis,'Demo startup');file=track.file||await track.readFile();r.inputFile={sha256:await sha(await file.arrayBuffer()),bytes:file.size};click('[data-panel="settings"]');const setting=$('[data-setting="Sync Mode"]');setting.value='Smart Sync';setting.dispatchEvent(new Event('change',{bubbles:true}));click('#save-settings');click('[data-panel="sampler"]');await until(()=>$('#sampler-output'),'Sampler');
  await engine.ctx.audioWorklet.addModule(new URL('./stem-activation-capture-145.js',import.meta.url));zero=engine.ctx.createConstantSource();zero.offset.value=0;stereo=engine.ctx.createChannelMerger(2);zero.connect(stereo,0,0);zero.connect(stereo,0,1);zero.start();r.zeroObserver={offset:0,channels:2};for(const label of ['bus','sample0','sample1','deck']){const input=engine.ctx.createGain(),split=engine.ctx.createChannelSplitter(2);stereo.connect(input);input.connect(split);taps.push({label,input});for(let c=0;c<2;c++){const w=new AudioWorkletNode(engine.ctx,'open-play-stem-activation-145-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});w.label=label;w.channel=c;split.connect(w,c);w.connect(engine.ctx.destination);witnesses.push(w);}}
  await configure(1,false);r.bystanderOwner=id(engine.samples.get(1));
  for(const name of ['preparation-own-stop','preparation-load','scheduled-own-stop','scheduled-source-stop']){
   await reset();const row={name,before:snap(),events:[]};r.stages.push(row);const prepare=engine.createForwardKeylock,synchronize=engine.synchronize;let called=false;
   const action=()=>{row.actionBefore=snap();if(name.endsWith('source-stop'))click('[data-sample="0:stop"]');else if(name==='preparation-load'){click('[data-track="demo-0"]');click('[data-deck="0"][data-action="load"]');}else click('[data-deck="0"][data-action="play"]');row.actionAfter=snap();};
   if(name.startsWith('preparation'))engine.createForwardKeylock=function(options){const real=prepare.call(this,options);if(!called){called=true;row.events.push({boundary:'actual-keylock-creation',at:engine.ctx.currentTime,signalAborted:options.signal.aborted});queueMicrotask(action);}return real;};
   else engine.synchronize=async function(deck,options){const result=await synchronize.call(this,deck,options);if(!called){called=true;row.events.push({boundary:'actual-synchronize-resolved',at:engine.ctx.currentTime,result:{...result}});queueMicrotask(action);}return result;};
   try{click('[data-deck="0"][data-action="play"]');await until(()=>called,'Actual observer boundary');await until(()=>!d.processing&&!d.playQueued,'Pending Play settled');await sleep(500);}finally{engine.createForwardKeylock=prepare;engine.synchronize=synchronize;}
   row.after=snap();attach();row.pcm=await capture(name==='scheduled-source-stop'?1.5:.3);row.last=snap();
  }
  r.inputFileUnchanged=await sha(await file.arrayBuffer())===r.inputFile.sha256;r.workflowExecuted=true;
 }catch(error){r.errors.push({message:error.message,stack:error.stack});r.failureState=snap();}
 finally{engine.stopAllSamples();for(const deck of state.decks)engine.pause(deck);for(const [source,dest]of connections)try{source.disconnect(dest);}catch{};if(zero){zero.stop();zero.disconnect();stereo.disconnect();}for(const w of witnesses){w.disconnect();w.port.close();}window.removeEventListener('unhandledrejection',unhandled);r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.workflowCompleted=!!r.workflowExecuted&&!r.errors.length&&!r.uiErrors.length&&r.sourceStable;const raw=JSON.stringify(r),ident=crypto.randomUUID().replaceAll('-','');let receipt;try{const response=await fetch('/api/test-evidence/stem-resource-150/'+ident,{method:'POST',headers:{'Content-Type':'application/json','X-Open-Play':'local-prototype'},body:raw});assert(response.ok,'Save original');receipt=await response.json();assert(receipt.sha256===await sha(new TextEncoder().encode(raw)),'Receipt mismatch');}catch(error){receipt={id:ident,error:error.message};}const summary={workflowCompleted:r.workflowCompleted,sourceStable:r.sourceStable,context:r.context,bystanderOwner:r.bystanderOwner,stages:r.stages.map(({pcm,...s})=>s),errors:r.errors,uiErrors:r.uiErrors,receipt};$('#music-original').textContent=JSON.stringify(summary);$('#music-results').textContent=JSON.stringify(summary,null,2);$('#music-status').textContent=r.workflowCompleted?'Ownership workflow recorded; independent inspection pending':'Failed workflow retained';}
}
async function boot(){assert(!localStorage.getItem('openplay-review-v1'),'Fresh origin required');localStorage.setItem('openplay-review-v1',JSON.stringify(await(await fetch('fixtures/sampler-fallback-178-short-loop.json')).json()));const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'App');app=window.openPlay;app.engine.init();app.engine.audioMonitor.mutePhysical(true);$('#music-status').textContent='Import the private research MP3';readiness=setInterval(()=>{if(app.state.tracks.some(t=>t.contentHash==='cb2e756d1fa4ce264767a4f6adbaf9e3f69a040db7889d830abdb429cc1a5ac3')){$('#music-run').disabled=false;$('#music-status').textContent='Imported track ready';}},250);}
